def task_func(directory):
    import os
    import pathlib
    from hashlib import md5
    import unicodedata

    def normalize_filename(filename):
        # Normalize filename using Unicode Normalization Form KD
        return unicodedata.normalize('NFKD', filename).encode('ascii', 'ignore').decode()

    def get_file_info(file_path):
        try:
            # Get file size in bytes
            file_size = os.path.getsize(file_path)

            # Calculate MD5 hash
            with open(file_path, 'rb') as f:
                file_hash = md5(f.read()).hexdigest()

            return {'Size': file_size, 'MD5 Hash': file_hash}
        except Exception as e:
            print(f"Error processing {file_path}: {e}")
            return None

    def process_directory(directory):
        result_dict = {}

        for root, _, files in os.walk(directory):
            for file_name in files:
                normalized_file_name = normalize_filename(file_name)

                if normalized_file_name not in result_dict:
                    result_dict[normalized_file_name] = []

                file_path = os.path.join(root, file_name)
                info = get_file_info(file_path)
                if info:
                    result_dict[normalized_file_name].append(info)

        return result_dict

    # Example usage
    directory_to_process = '/path/to/your/directory'
    result = process_directory(directory_to_process)

    for normalized_name, file_info_list in result.items():
        print(f"{normalized_name}:")
        for info in file_info_list:
            print(f"  Size: {info['Size']}, MD5 Hash: {info['MD5 Hash']}")

