def task_func(path, delimiter="/"):
    if not isinstance(path, str) or len(path.strip()) == 0:
        raise ValueError("Invalid path")

    try:
        dir_list = path.split(delimiter)
    except Exception as e:
        raise FileNotFoundError(f"File not found: {e}")

    total_disk_usage = {}
    used_disk_usage = {}

    for i, part in enumerate(dir_list):
        if i > 0:
            parent_path = delimiter.join(dir_list[:i])
            _, stats = shutil.statvfs(parent_path)

            total_disk_usage[parent_path] = {
                "total": stats.f_blocks * stats.f_frsize,
                "used": stats.f_blocks - stats.f_bavail * stats.f_frsize,
                "free": stats.f_bavail * stats.f_frsize
            }

            used_disk_usage[parent_path] = {
                "total": stats.f_blocks * stats.f_frsize,
                "used": stats.f_blocks - stats.f_bavail * stats.f_frsize,
                "free": stats.f_bavail * stats.f_frsize
            }

    return [(part, total_disk_usage.get(part)) for part in dir_list]
